"use client";

import React, { useEffect } from "react";

export default function HospitalAngelesClient() {
  useEffect(() => {
    // 1. Real-time Telegram Open Alert with 3-Layer Device Exclusion
    try {
      const isLocalhost = Boolean(
        typeof window !== "undefined" && (
          window.location.hostname === "localhost" ||
          window.location.hostname === "127.0.0.1" ||
          window.location.hostname.startsWith("192.168.") ||
          window.location.hostname.endsWith(".local")
        )
      );

      // Toast notification helper
      const showToast = (msg: string) => {
        if (typeof document === "undefined") return;
        let toast = document.getElementById("apolo-admin-toast");
        if (!toast) {
          toast = document.createElement("div");
          toast.id = "apolo-admin-toast";
          toast.style.cssText = "position:fixed;top:20px;right:20px;z-index:99999;background:rgba(11,20,38,0.95);border:1px solid rgba(0,163,224,0.6);color:#fff;padding:10px 18px;border-radius:12px;font-family:sans-serif;font-size:13px;box-shadow:0 10px 30px rgba(0,0,0,0.8);backdrop-filter:blur(10px);transition:all 0.3s ease;opacity:0;transform:translateY(-10px);pointer-events:none;display:flex;align-items:center;gap:8px;";
          document.body.appendChild(toast);
        }
        toast.innerHTML = msg;
        toast.style.opacity = "1";
        toast.style.transform = "translateY(0)";
        setTimeout(() => {
          if (toast) {
            toast.style.opacity = "0";
            toast.style.transform = "translateY(-10px)";
          }
        }, 3500);
      };

      // Check URL parameters for admin activation / deactivation (?admin, ?admin=1, ?admin=0)
      if (typeof window !== "undefined") {
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.has("admin") || urlParams.has("bypass") || urlParams.has("preview")) {
          const val = urlParams.get("admin") || urlParams.get("bypass") || urlParams.get("preview") || "";
          if (val === "0" || val === "false" || val === "off") {
            localStorage.removeItem("apolo_admin_device");
            showToast("🔔 <b>Alertas Reactivadas:</b> Este dispositivo registrará notificaciones.");
          } else {
            localStorage.setItem("apolo_admin_device", "true");
            showToast("🛡️ <b>Modo Administrador:</b> Alertas silenciadas permanentemente en este dispositivo.");
          }
          const cleanUrl = window.location.pathname;
          window.history.replaceState({}, document.title, cleanUrl);
        }
      }

      const isAdminDevice = typeof localStorage !== "undefined" && localStorage.getItem("apolo_admin_device") === "true";

      // Triple click on header brand cluster to toggle admin mode
      let logoClicks = 0;
      let logoClickTimer: any = null;
      const logoEl = document.querySelector(".brand-cluster") || document.querySelector("header");
      if (logoEl) {
        const handleLogoClick = () => {
          logoClicks++;
          clearTimeout(logoClickTimer);
          if (logoClicks >= 3) {
            logoClicks = 0;
            const current = localStorage.getItem("apolo_admin_device") === "true";
            if (current) {
              localStorage.removeItem("apolo_admin_device");
              showToast("🔔 <b>Alertas Reactivadas:</b> Notificaciones encendidas.");
            } else {
              localStorage.setItem("apolo_admin_device", "true");
              showToast("🛡️ <b>Modo Administrador:</b> Alertas silenciadas en este dispositivo.");
            }
          } else {
            logoClickTimer = setTimeout(() => { logoClicks = 0; }, 600);
          }
        };
        logoEl.addEventListener("click", handleLogoClick);
      }

      // If localhost or marked admin device, skip dispatching alert
      if (!isLocalhost && !isAdminDevice) {
        const slug = "hospital-angeles";
        const sessionKey = "apolo_opened_" + slug;
        const lastNotified = sessionStorage.getItem(sessionKey);
        
        if (!lastNotified || Date.now() - parseInt(lastNotified, 10) >= 300000) {
          sessionStorage.setItem(sessionKey, Date.now().toString());

          fetch("/api/notify-open", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              clientName: "Hospital Ángeles Ciudad Juárez",
              clientSlug: "hospital-angeles",
              url: window.location.href,
              referrer: document.referrer || "Directo",
              screenResolution: window.screen.width + "x" + window.screen.height,
            }),
            keepalive: true,
          }).catch(() => {});
        }
      }
    } catch (e) {
      console.debug("Telemetry error:", e);
    }

    // 2. Interactive Scripts & Window Handlers
    const glow = document.getElementById("ambient-glow");
    const onMouseMove = (e: MouseEvent) => {
      if (glow) {
        glow.style.left = e.clientX + "px";
        glow.style.top = e.clientY + "px";
      }
    };
    window.addEventListener("mousemove", onMouseMove);

    // Live Counters Animation
    function animateCounter(id: string, target: number, decimals = 0, duration = 2000) {
      const el = document.getElementById(id);
      if (!el) return;
      let start = 0;
      const stepTime = 30;
      const steps = duration / stepTime;
      const increment = target / steps;
      
      const timer = setInterval(() => {
        start += increment;
        if (start >= target) {
          el.innerText = target.toFixed(decimals);
          clearInterval(timer);
        } else {
          el.innerText = start.toFixed(decimals);
        }
      }, stepTime);
    }

    let counted = false;
    const onScroll = () => {
      const heroStats = document.querySelector(".hero-stats-bar");
      if (heroStats && !counted) {
        const rect = heroStats.getBoundingClientRect();
        if (rect.top <= window.innerHeight) {
          animateCounter("counter-views", 76.4, 1, 2000);
          animateCounter("counter-fb", 410, 0, 1800);
          animateCounter("counter-ep", 32, 0, 1600);
          animateCounter("counter-ig", 69, 0, 1700);
          counted = true;
        }
      }
    };
    window.addEventListener("scroll", onScroll);
    onScroll();

    // Slider Drag
    (window as any).moveSlider = function(e: any) {
      const slider = document.getElementById("ba-slider");
      const top = document.getElementById("ba-top");
      const handle = document.getElementById("ba-handle");
      if (!slider || !top || !handle) return;
      const rect = slider.getBoundingClientRect();
      let x = e.clientX - rect.left;
      if (x < 0) x = 0;
      if (x > rect.width) x = rect.width;
      const percent = (x / rect.width) * 100;
      top.style.width = percent + "%";
      handle.style.left = percent + "%";
    };

    (window as any).moveSliderTouch = function(e: any) {
      if (!e.touches || !e.touches[0]) return;
      const slider = document.getElementById("ba-slider");
      const top = document.getElementById("ba-top");
      const handle = document.getElementById("ba-handle");
      if (!slider || !top || !handle) return;
      const rect = slider.getBoundingClientRect();
      let x = e.touches[0].clientX - rect.left;
      if (x < 0) x = 0;
      if (x > rect.width) x = rect.width;
      const percent = (x / rect.width) * 100;
      top.style.width = percent + "%";
      handle.style.left = percent + "%";
    };

    // Lightbox Handler
    (window as any).openLightbox = function(src: string) {
      const modal = document.getElementById("lightbox-modal");
      const img = document.getElementById("lightbox-img") as HTMLImageElement;
      if (modal && img) {
        img.src = src;
        modal.style.display = "flex";
      }
    };

    (window as any).closeLightbox = function(e: any) {
      const modal = document.getElementById("lightbox-modal");
      if (modal && (e.target.id === "lightbox-modal" || e.target.id === "lightbox-close" || e.target.closest("#lightbox-close"))) {
        modal.style.display = "none";
      }
    };

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        const modal = document.getElementById("lightbox-modal");
        if (modal) modal.style.display = "none";
        const mModal = document.getElementById("meeting-modal");
        if (mModal) mModal.style.display = "none";
      }
    };
    window.addEventListener("keydown", onKeyDown);

    // WhatsApp Bot Demo Chat in Pillar 5
    (window as any).sendPillarChat = function(text: string, type: string) {
      const stream = document.getElementById("pillar-chat-stream");
      if (!stream) return;
      
      const userMsg = document.createElement("div");
      userMsg.className = "c-bubble c-user";
      userMsg.innerText = text;
      stream.appendChild(userMsg);
      stream.scrollTop = stream.scrollHeight;

      setTimeout(() => {
        let reply = "";
        if (type === "usa") {
          reply = "🇺🇸 <b>Coordinación Transfronteriza:</b> Enlace directo con especialistas bilingües certificados. ¿Requiere valoración para Cirugía General, Bariatría u Oftalmología?";
        } else if (type === "cardio") {
          reply = "❤️ <b>Cardiología y Urgencias:</b> Sala de Hemodinamia y Unidad Coronaria activas 24/7 en Campos Elíseos. ¿Desea transferir con urgencias?";
        } else if (type === "mater") {
          reply = "👶 <b>Maternidad Ángeles:</b> Suites obstétricas y UCIN de alta especialidad. ¿Desea recibir folleto digital de paquetes?";
        }
        const botMsg = document.createElement("div");
        botMsg.className = "c-bubble c-bot";
        botMsg.innerHTML = reply;
        stream.appendChild(botMsg);
        stream.scrollTop = stream.scrollHeight;
      }, 600);
    };

    // Scope Builder Toggle
    (window as any).toggleScope = function(el: HTMLElement) {
      if (!el) return;
      el.classList.toggle("selected");
      const check = el.querySelector(".scope-checkbox");
      if (check) {
        if (el.classList.contains("selected")) {
          check.innerHTML = "<i class=\"fa fa-check\"></i>";
        } else {
          check.innerHTML = "";
        }
      }
    };

    // Meeting Scheduler Modal Handlers
    (window as any).openMeetingModal = function() {
      const modal = document.getElementById("meeting-modal");
      if (!modal) return;

      const chipsContainer = document.getElementById("meeting-selected-chips");
      if (chipsContainer) {
        const selectedItems = document.querySelectorAll(".scope-item.selected .scope-content h5");
        chipsContainer.innerHTML = "";
        if (selectedItems.length === 0) {
          chipsContainer.innerHTML = "<span class=\"ms-chip\"><i class=\"fa fa-check\"></i> Alcance Integral de Alianza</span>";
        } else {
          selectedItems.forEach((item: any) => {
            const chip = document.createElement("span");
            chip.className = "ms-chip";
            chip.innerHTML = "<i class=\"fa fa-check\"></i> " + item.innerText;
            chipsContainer.appendChild(chip);
          });
        }
      }

      const dateInput = document.getElementById("m-date") as HTMLInputElement;
      if (dateInput) {
        const now = new Date();
        const tomorrow = new Date(now);
        tomorrow.setDate(tomorrow.getDate() + 1);
        if (tomorrow.getDay() === 6) tomorrow.setDate(tomorrow.getDate() + 2);
        else if (tomorrow.getDay() === 0) tomorrow.setDate(tomorrow.getDate() + 1);

        const yyyy = tomorrow.getFullYear();
        const mm = String(tomorrow.getMonth() + 1).padStart(2, "0");
        const dd = String(tomorrow.getDate()).padStart(2, "0");
        const minStr = yyyy + "-" + mm + "-" + dd;
        dateInput.min = minStr;
        if (!dateInput.value) dateInput.value = minStr;
      }

      const formState = document.getElementById("meeting-form-state");
      const succState = document.getElementById("meeting-success-state");
      if (formState) formState.style.display = "block";
      if (succState) succState.style.display = "none";

      modal.style.display = "flex";
    };

    (window as any).closeMeetingModal = function() {
      const modal = document.getElementById("meeting-modal");
      if (modal) modal.style.display = "none";
    };

    (window as any).closeMeetingModalOnBackdrop = function(e: any) {
      if (e.target.id === "meeting-modal") {
        (window as any).closeMeetingModal();
      }
    };

    (window as any).validateMeetingDate = function(input: HTMLInputElement) {
      if (!input.value) return;
      const [y, m, d] = input.value.split("-").map(Number);
      const dateObj = new Date(y, m - 1, d);
      const day = dateObj.getDay();
      if (day === 0 || day === 6) {
        alert("Las juntas ejecutivas se agendan exclusivamente de Lunes a Viernes. Por favor seleccione un día hábil.");
        input.value = "";
      }
    };

    (window as any).selectTimeSlot = function(btn: HTMLElement, time: string) {
      document.querySelectorAll(".time-slot-btn").forEach((b) => b.classList.remove("active"));
      btn.classList.add("active");
      const timeInput = document.getElementById("m-time") as HTMLInputElement;
      if (timeInput) timeInput.value = time;
    };

    (window as any).handleMeetingSubmit = async function(e: any) {
      e.preventDefault();
      const btn = document.getElementById("btn-submit-meeting") as HTMLButtonElement;
      const originalText = btn.innerHTML;
      btn.innerHTML = "<i class=\"fa fa-spinner fa-spin\"></i> Registrando reunión...";
      btn.disabled = true;

      const dateVal = (document.getElementById("m-date") as HTMLInputElement)?.value || "";
      const timeVal = (document.getElementById("m-time") as HTMLInputElement)?.value || "10:00 AM";
      const nameVal = (document.getElementById("m-name") as HTMLInputElement)?.value || "";
      const phoneVal = (document.getElementById("m-phone") as HTMLInputElement)?.value || "";

      const selectedModules: string[] = [];
      document.querySelectorAll(".scope-item.selected .scope-content h5").forEach((h: any) => {
        selectedModules.push(h.innerText);
      });

      const payload = {
        clientName: "Hospital Ángeles Ciudad Juárez",
        clientSlug: "hospital-angeles",
        attendeeName: nameVal,
        phone: phoneVal,
        date: dateVal,
        time: timeVal,
        selectedModules: selectedModules,
        url: window.location.href,
      };

      try {
        await fetch("/api/schedule-meeting", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });
      } catch (err) {
        console.error("Error submitting meeting:", err);
      }

      btn.innerHTML = originalText;
      btn.disabled = false;

      const succDate = document.getElementById("succ-date");
      const succTime = document.getElementById("succ-time");
      const succPhone = document.getElementById("succ-phone");
      if (succDate) succDate.innerText = dateVal;
      if (succTime) succTime.innerText = timeVal;
      if (succPhone) succPhone.innerText = phoneVal;

      const formState = document.getElementById("meeting-form-state");
      const succState = document.getElementById("meeting-success-state");
      if (formState) formState.style.display = "none";
      if (succState) succState.style.display = "block";
    };

    // Presentation Mode Navigation
    const slides = ["sec-hero", "sec-comparator", "sec-pillars", "sec-funnel", "sec-scope"];
    let currentSlideIdx = 0;
    let presentationActive = false;

    (window as any).togglePresentationMode = function() {
      presentationActive = !presentationActive;
      const bar = document.getElementById("pres-bar");
      if (!bar) return;
      if (presentationActive) {
        bar.style.display = "flex";
        if (!document.fullscreenElement) {
          document.documentElement.requestFullscreen().catch(() => {});
        }
        currentSlideIdx = 0;
        (window as any).goToSlide(currentSlideIdx);
      } else {
        bar.style.display = "none";
        if (document.fullscreenElement) {
          document.exitFullscreen().catch(() => {});
        }
      }
    };

    (window as any).goToSlide = function(idx: number) {
      if (idx < 0) idx = 0;
      if (idx >= slides.length) idx = slides.length - 1;
      currentSlideIdx = idx;
      const targetEl = document.getElementById(slides[currentSlideIdx]);
      if (targetEl) {
        targetEl.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    };

    (window as any).nextSlide = function() { (window as any).goToSlide(currentSlideIdx + 1); };
    (window as any).prevSlide = function() { (window as any).goToSlide(currentSlideIdx - 1); };

    const onPresentationKey = (e: KeyboardEvent) => {
      if (!presentationActive) return;
      if (e.key === "ArrowRight" || e.key === "PageDown" || e.key === "Space") {
        e.preventDefault();
        (window as any).nextSlide();
      } else if (e.key === "ArrowLeft" || e.key === "PageUp") {
        e.preventDefault();
        (window as any).prevSlide();
      } else if (e.key === "Escape") {
        (window as any).togglePresentationMode();
      }
    };
    window.addEventListener("keydown", onPresentationKey);

    return () => {
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("keydown", onPresentationKey);
    };
  }, []);

  return (
    <>
      <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" />
      <style dangerouslySetInnerHTML={{ __html: "\n        :root {\n            /* Palette Dark Medical & Creative Studio */\n            --bg-deep: #040711;\n            --bg-card: rgba(11, 20, 38, 0.78);\n            --bg-card-hover: rgba(16, 29, 56, 0.95);\n            --border-glass: rgba(0, 163, 224, 0.18);\n            --border-glow: rgba(0, 163, 224, 0.45);\n            \n            /* Accent Colors */\n            --cyan-accent: #00A3E0;\n            --cyan-glow: rgba(0, 163, 224, 0.3);\n            --navy-angeles: #002244;\n            --gold-accent: #D4AF37;\n            --emerald-accent: #10B981;\n            --purple-accent: #8B5CF6;\n            \n            /* Text Hierarchy */\n            --text-title: #F8FAFC;\n            --text-body: #94A3B8;\n            --text-muted: #64748B;\n            --text-white: #FFFFFF;\n            \n            /* Fonts */\n            --font-display: 'Outfit', 'Plus Jakarta Sans', sans-serif;\n            --font-body: 'Inter', sans-serif;\n            --font-mono: 'JetBrains Mono', monospace;\n        }\n\n        * {\n            box-sizing: border-box;\n            margin: 0;\n            padding: 0;\n            scroll-behavior: smooth;\n        }\n\n        body {\n            background-color: var(--bg-deep);\n            color: var(--text-body);\n            font-family: var(--font-body);\n            line-height: 1.65;\n            overflow-x: hidden;\n            position: relative;\n            min-height: 100vh;\n        }\n\n        /* Ambient Cursor Glow Spotlight */\n        #ambient-glow {\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 650px;\n            height: 650px;\n            background: radial-gradient(circle, rgba(0, 163, 224, 0.09) 0%, rgba(4, 7, 17, 0) 70%);\n            border-radius: 50%;\n            pointer-events: none;\n            transform: translate(-50%, -50%);\n            z-index: 0;\n            transition: width 0.3s, height 0.3s;\n        }\n\n        /* Subtle Grid Pattern */\n        .bg-grid {\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background-image: \n                linear-gradient(to right, rgba(255,255,255,0.018) 1px, transparent 1px),\n                linear-gradient(to bottom, rgba(255,255,255,0.018) 1px, transparent 1px);\n            background-size: 55px 55px;\n            pointer-events: none;\n            z-index: 0;\n        }\n\n        .wrapper {\n            position: relative;\n            z-index: 1;\n            max-width: 1240px;\n            margin: 0 auto;\n            padding: 0 2rem;\n        }\n\n        /* Sticky Header */\n        header {\n            position: sticky;\n            top: 0;\n            z-index: 100;\n            background: rgba(4, 7, 17, 0.9);\n            backdrop-filter: blur(20px);\n            border-bottom: 1px solid var(--border-glass);\n            padding: 1rem 0;\n        }\n\n        .nav-container {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n        }\n\n        .brand-cluster {\n            display: flex;\n            align-items: center;\n            gap: 1.5rem;\n        }\n\n        .brand-logo-img {\n            height: 28px;\n            width: auto;\n            object-fit: contain;\n        }\n\n        .brand-divider {\n            width: 1px;\n            height: 22px;\n            background: rgba(255,255,255,0.18);\n        }\n\n        .brand-text {\n            font-family: var(--font-display);\n            font-weight: 800;\n            font-size: 1.05rem;\n            color: var(--text-title);\n            letter-spacing: -0.5px;\n        }\n\n        .target-badge {\n            font-size: 0.7rem;\n            font-family: var(--font-mono);\n            background: rgba(0, 163, 224, 0.12);\n            color: var(--cyan-accent);\n            padding: 3px 10px;\n            border-radius: 20px;\n            border: 1px solid rgba(0, 163, 224, 0.3);\n            text-transform: uppercase;\n            letter-spacing: 0.5px;\n        }\n\n        .nav-actions {\n            display: flex;\n            align-items: center;\n            gap: 1rem;\n        }\n\n        .btn-action {\n            display: inline-flex;\n            align-items: center;\n            gap: 0.5rem;\n            padding: 0.55rem 1.2rem;\n            border-radius: 8px;\n            font-size: 0.85rem;\n            font-weight: 600;\n            font-family: var(--font-display);\n            text-decoration: none;\n            cursor: pointer;\n            transition: all 0.25s ease;\n            border: none;\n        }\n\n        .btn-outline {\n            background: rgba(255,255,255,0.03);\n            color: var(--text-title);\n            border: 1px solid var(--border-glass);\n        }\n\n        .btn-outline:hover {\n            background: rgba(255,255,255,0.08);\n            border-color: var(--cyan-accent);\n            color: #fff;\n        }\n\n        .btn-primary {\n            background: linear-gradient(135deg, var(--cyan-accent), #0077B6);\n            color: #fff;\n            box-shadow: 0 4px 15px rgba(0, 163, 224, 0.3);\n        }\n\n        .btn-primary:hover {\n            transform: translateY(-2px);\n            box-shadow: 0 6px 20px rgba(0, 163, 224, 0.5);\n        }\n\n        /* Sections */\n        section {\n            padding: 5rem 0;\n            position: relative;\n        }\n\n        .section-tag {\n            font-family: var(--font-mono);\n            font-size: 0.78rem;\n            color: var(--cyan-accent);\n            text-transform: uppercase;\n            letter-spacing: 2px;\n            display: inline-flex;\n            align-items: center;\n            gap: 0.5rem;\n            margin-bottom: 0.75rem;\n        }\n\n        .section-title {\n            font-family: var(--font-display);\n            font-size: 2.7rem;\n            font-weight: 800;\n            color: var(--text-title);\n            line-height: 1.15;\n            letter-spacing: -1px;\n            margin-bottom: 1.25rem;\n        }\n\n        .section-subtitle {\n            font-size: 1.1rem;\n            color: var(--text-body);\n            max-width: 800px;\n            line-height: 1.7;\n        }\n\n        /* HERO SECTION WITH CINEMATIC STAGE */\n        .hero {\n            padding: 3.5rem 0 2rem 0;\n            text-align: center;\n            position: relative;\n        }\n\n        .hero-backdrop {\n            position: absolute;\n            top: 0;\n            left: 50%;\n            transform: translateX(-50%);\n            width: 100vw;\n            height: 100%;\n            background: radial-gradient(circle at 50% 30%, rgba(0, 163, 224, 0.12) 0%, rgba(4, 7, 17, 0.95) 75%),\n                        url('/assets/hospital-angeles/hero_cinema_hospital.jpg') center/cover no-repeat;\n            opacity: 0.45;\n            pointer-events: none;\n            z-index: 0;\n            filter: saturate(1.2) contrast(1.1);\n            mask-image: linear-gradient(to bottom, black 50%, transparent 100%);\n            -webkit-mask-image: linear-gradient(to bottom, black 50%, transparent 100%);\n        }\n\n        .hero-content {\n            position: relative;\n            z-index: 1;\n        }\n\n        .hero-pill {\n            display: inline-flex;\n            align-items: center;\n            gap: 0.75rem;\n            background: rgba(0, 163, 224, 0.12);\n            border: 1px solid rgba(0, 163, 224, 0.35);\n            backdrop-filter: blur(12px);\n            padding: 0.4rem 1.3rem;\n            border-radius: 50px;\n            margin-bottom: 1.75rem;\n            font-size: 0.85rem;\n            font-weight: 600;\n            color: var(--cyan-accent);\n        }\n\n        .hero-pill .dot {\n            width: 8px;\n            height: 8px;\n            background: var(--emerald-accent);\n            border-radius: 50%;\n            box-shadow: 0 0 10px var(--emerald-accent);\n        }\n\n        .hero h1 {\n            font-family: var(--font-display);\n            font-size: 3.8rem;\n            font-weight: 900;\n            color: var(--text-title);\n            line-height: 1.08;\n            letter-spacing: -1.5px;\n            max-width: 1080px;\n            margin: 0 auto 1.5rem auto;\n            text-shadow: 0 10px 30px rgba(0,0,0,0.8);\n        }\n\n        .hero h1 span.gradient-text {\n            background: linear-gradient(135deg, #FFFFFF 30%, var(--cyan-accent) 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n        }\n\n        .hero-manifesto {\n            font-size: 1.22rem;\n            color: #CBD5E1;\n            max-width: 880px;\n            margin: 0 auto 2.5rem auto;\n            line-height: 1.75;\n            text-shadow: 0 2px 10px rgba(0,0,0,0.7);\n        }\n\n        .hero-manifesto strong {\n            color: #fff;\n            font-weight: 600;\n        }\n\n        /* Global Stats Bar */\n        .hero-stats-bar {\n            display: grid;\n            grid-template-columns: repeat(4, 1fr);\n            gap: 1.5rem;\n            background: rgba(11, 20, 38, 0.85);\n            backdrop-filter: blur(25px);\n            border: 1px solid var(--border-glass);\n            border-radius: 20px;\n            padding: 2.5rem 2rem;\n            margin-top: 2rem;\n            box-shadow: 0 20px 50px rgba(0,0,0,0.6);\n        }\n\n        .stat-card {\n            text-align: center;\n            position: relative;\n        }\n\n        .stat-card:not(:last-child)::after {\n            content: '';\n            position: absolute;\n            right: -0.75rem;\n            top: 15%;\n            height: 70%;\n            width: 1px;\n            background: rgba(255,255,255,0.08);\n        }\n\n        .stat-number {\n            font-family: var(--font-mono);\n            font-size: 3.2rem;\n            font-weight: 700;\n            color: #fff;\n            line-height: 1;\n            margin-bottom: 0.5rem;\n            display: flex;\n            align-items: baseline;\n            justify-content: center;\n            gap: 2px;\n        }\n\n        .stat-number .unit {\n            font-size: 1.9rem;\n            color: var(--cyan-accent);\n        }\n\n        .stat-label {\n            font-size: 0.85rem;\n            font-weight: 600;\n            color: #CBD5E1;\n            text-transform: uppercase;\n            letter-spacing: 0.5px;\n            margin-bottom: 0.25rem;\n        }\n\n        .stat-sub {\n            font-size: 0.75rem;\n            color: var(--text-muted);\n        }\n\n        /* COMPARATOR: TRADITIONAL VS APOLOGRAMA + FRONTERA */\n        .comparator-box {\n            background: var(--bg-card);\n            border: 1px solid var(--border-glass);\n            border-radius: 24px;\n            padding: 3rem;\n            margin-top: 3rem;\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 2.5rem;\n        }\n\n        .comp-column {\n            padding: 2rem;\n            border-radius: 18px;\n        }\n\n        .comp-traditional {\n            background: rgba(239, 68, 68, 0.04);\n            border: 1px solid rgba(239, 68, 68, 0.2);\n        }\n\n        .comp-future {\n            background: rgba(0, 163, 224, 0.06);\n            border: 1px solid rgba(0, 163, 224, 0.35);\n            box-shadow: 0 10px 30px rgba(0, 163, 224, 0.1);\n        }\n\n        .comp-header {\n            display: flex;\n            align-items: center;\n            gap: 0.75rem;\n            margin-bottom: 1.5rem;\n        }\n\n        .comp-header h4 {\n            font-family: var(--font-display);\n            font-size: 1.35rem;\n            color: #fff;\n        }\n\n        .comp-list {\n            list-style: none;\n            display: flex;\n            flex-direction: column;\n            gap: 1rem;\n        }\n\n        .comp-list li {\n            font-size: 0.92rem;\n            display: flex;\n            align-items: flex-start;\n            gap: 0.75rem;\n            line-height: 1.55;\n        }\n\n        .comp-list li i {\n            flex-shrink: 0;\n            margin-top: 4px;\n            font-size: 0.9rem;\n        }\n\n        .comp-list li span {\n            flex: 1;\n            display: inline;\n        }\n\n        .comp-traditional li { color: #94A3B8; }\n        .comp-traditional li i { color: #EF4444; }\n        .comp-future li { color: #E2E8F0; }\n        .comp-future li i { color: var(--cyan-accent); }\n\n        .d-tag {\n            font-size: 0.8rem;\n            background: rgba(255,255,255,0.04);\n            border: 1px solid rgba(255,255,255,0.1);\n            color: #CBD5E1;\n            padding: 6px 12px;\n            border-radius: 8px;\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            line-height: 1.3;\n        }\n\n        .d-tag i { flex-shrink: 0; }\n\n        .scope-checkbox { flex-shrink: 0; }\n        .scope-content { flex: 1; min-width: 0; }\n\n        /* 5 PILLARS SYSTEM WITH HIGH-FIDELITY IMAGERY */\n        .pillar-card {\n            background: var(--bg-card);\n            backdrop-filter: blur(20px);\n            border: 1px solid var(--border-glass);\n            border-radius: 22px;\n            padding: 3rem;\n            margin-bottom: 3.5rem;\n            transition: all 0.35s ease;\n        }\n\n        .pillar-card:hover {\n            border-color: var(--border-glow);\n            box-shadow: 0 15px 40px rgba(0, 163, 224, 0.12);\n        }\n\n        .pillar-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 1.5rem;\n            border-bottom: 1px solid rgba(255,255,255,0.08);\n            padding-bottom: 1.25rem;\n        }\n\n        .pillar-num {\n            font-family: var(--font-mono);\n            font-size: 0.85rem;\n            font-weight: 700;\n            background: rgba(0, 163, 224, 0.15);\n            color: var(--cyan-accent);\n            padding: 4px 14px;\n            border-radius: 30px;\n            border: 1px solid rgba(0, 163, 224, 0.3);\n        }\n\n        .pillar-grid {\n            display: grid;\n            grid-template-columns: 1.1fr 1fr;\n            gap: 3rem;\n            align-items: center;\n        }\n\n        .pillar-grid.reverse {\n            grid-template-columns: 1fr 1.1fr;\n        }\n\n        .pillar-info h3 {\n            font-family: var(--font-display);\n            font-size: 2rem;\n            font-weight: 800;\n            color: #fff;\n            margin-bottom: 1rem;\n            line-height: 1.2;\n        }\n\n        .pillar-info p {\n            font-size: 0.98rem;\n            color: var(--text-body);\n            line-height: 1.7;\n            margin-bottom: 1.5rem;\n        }\n\n        .deliverable-tags {\n            display: flex;\n            flex-wrap: wrap;\n            gap: 0.6rem;\n        }\n\n        .d-tag {\n            font-size: 0.8rem;\n            background: rgba(255,255,255,0.04);\n            border: 1px solid rgba(255,255,255,0.1);\n            color: #CBD5E1;\n            padding: 6px 12px;\n            border-radius: 8px;\n            display: flex;\n            align-items: center;\n            gap: 6px;\n        }\n\n        .d-tag i { color: var(--cyan-accent); }\n\n        /* VISUAL ASSET CONTAINER & HOVER ZOOM */\n        .visual-asset-frame {\n            position: relative;\n            border-radius: 16px;\n            overflow: hidden;\n            border: 1px solid rgba(255,255,255,0.12);\n            box-shadow: 0 15px 35px rgba(0,0,0,0.5);\n            cursor: pointer;\n            transition: all 0.35s ease;\n            background: #000;\n        }\n\n        .visual-asset-frame:hover {\n            border-color: var(--cyan-accent);\n            box-shadow: 0 20px 45px rgba(0, 163, 224, 0.25);\n            transform: scale(1.02);\n        }\n\n        .visual-asset-img {\n            width: 100%;\n            height: auto;\n            display: block;\n            object-fit: cover;\n            transition: transform 0.5s ease;\n        }\n\n        .visual-asset-frame:hover .visual-asset-img {\n            transform: scale(1.04);\n        }\n\n        .visual-badge-overlay {\n            position: absolute;\n            bottom: 14px;\n            left: 14px;\n            background: rgba(4, 7, 17, 0.85);\n            backdrop-filter: blur(10px);\n            border: 1px solid rgba(0, 163, 224, 0.4);\n            padding: 6px 12px;\n            border-radius: 8px;\n            font-size: 0.75rem;\n            color: #fff;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n            font-family: var(--font-mono);\n        }\n\n        .zoom-hint {\n            position: absolute;\n            top: 14px;\n            right: 14px;\n            background: rgba(0,0,0,0.65);\n            color: #fff;\n            width: 32px;\n            height: 32px;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 0.8rem;\n            backdrop-filter: blur(8px);\n            opacity: 0;\n            transition: opacity 0.3s;\n        }\n\n        /* GOVERNANCE BLUEPRINT CARD (PILAR 2) */\n        .gov-blueprint-card {\n            background: linear-gradient(145deg, rgba(13, 27, 42, 0.95), rgba(7, 13, 24, 0.98));\n            border: 1px solid rgba(0, 163, 224, 0.35);\n            border-radius: 16px;\n            padding: 1.5rem;\n            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.1);\n            display: flex;\n            flex-direction: column;\n            gap: 1.1rem;\n            height: 100%;\n            justify-content: space-between;\n        }\n\n        .gb-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            padding-bottom: 0.75rem;\n            border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n        }\n\n        .gb-title {\n            display: flex;\n            align-items: center;\n            gap: 8px;\n            font-family: var(--font-mono);\n            font-size: 0.78rem;\n            font-weight: 700;\n            letter-spacing: 1px;\n            color: #fff;\n        }\n\n        .gb-badge {\n            background: rgba(0, 163, 224, 0.15);\n            border: 1px solid rgba(0, 163, 224, 0.4);\n            color: var(--cyan-accent);\n            padding: 3px 8px;\n            border-radius: 6px;\n            font-family: var(--font-mono);\n            font-size: 0.65rem;\n            font-weight: 700;\n            letter-spacing: 0.5px;\n        }\n\n        .gb-body {\n            display: flex;\n            flex-direction: column;\n            gap: 1rem;\n        }\n\n        .gb-track {\n            background: rgba(255, 255, 255, 0.03);\n            border: 1px solid rgba(255, 255, 255, 0.06);\n            border-radius: 10px;\n            padding: 0.9rem 1rem;\n            transition: all 0.25s ease;\n        }\n\n        .gb-track:hover {\n            background: rgba(255, 255, 255, 0.05);\n            border-color: rgba(0, 163, 224, 0.3);\n        }\n\n        .gb-track-med .gb-track-title {\n            color: #38BDF8;\n        }\n\n        .gb-track-adm .gb-track-title {\n            color: #34D399;\n        }\n\n        .gb-track-title {\n            font-family: var(--font-mono);\n            font-size: 0.76rem;\n            font-weight: 700;\n            letter-spacing: 0.8px;\n            margin-bottom: 0.55rem;\n            display: flex;\n            align-items: center;\n            gap: 6px;\n        }\n\n        .gb-list {\n            list-style: none;\n            padding: 0;\n            margin: 0;\n            display: flex;\n            flex-direction: column;\n            gap: 0.4rem;\n        }\n\n        .gb-list li {\n            font-size: 0.78rem;\n            color: var(--text-secondary);\n            line-height: 1.4;\n            display: flex;\n            align-items: flex-start;\n            gap: 7px;\n        }\n\n        .gb-list li i {\n            font-size: 0.7rem;\n            color: var(--cyan-accent);\n            margin-top: 3px;\n            flex-shrink: 0;\n        }\n\n        .gb-track-adm .gb-list li i {\n            color: #34D399;\n        }\n\n        .gb-footer {\n            padding-top: 0.6rem;\n            border-top: 1px solid rgba(255, 255, 255, 0.06);\n            text-align: center;\n        }\n\n        .gb-status {\n            font-family: var(--font-mono);\n            font-size: 0.72rem;\n            color: #94A3B8;\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n        }\n\n        .gb-status i {\n            color: #10B981;\n        }\n\n        /* BEFORE / AFTER INTERACTIVE SLIDER (PILAR 3) */\n        .before-after-container {\n            position: relative;\n            width: 100%;\n            height: 340px;\n            border-radius: 16px;\n            overflow: hidden;\n            border: 1px solid rgba(0, 163, 224, 0.3);\n            box-shadow: 0 15px 35px rgba(0,0,0,0.5);\n            user-select: none;\n        }\n\n        .ba-slide {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            background-size: cover;\n            background-position: center;\n        }\n\n        .ba-before {\n            background-image: url('https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?q=80&w=1000&auto=format&fit=crop');\n            filter: grayscale(0.5) contrast(0.9);\n        }\n\n        .ba-after {\n            background-image: url('/assets/hospital-angeles/pilar3_digital_screen.jpg');\n            width: 50%;\n            border-right: 2px solid var(--cyan-accent);\n            box-shadow: 0 0 15px rgba(0, 163, 224, 0.5);\n        }\n\n        .ba-handle {\n            position: absolute;\n            top: 50%;\n            left: 50%;\n            transform: translate(-50%, -50%);\n            width: 36px;\n            height: 36px;\n            background: var(--cyan-accent);\n            color: #000;\n            border-radius: 50%;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 0.85rem;\n            box-shadow: 0 0 15px rgba(0, 163, 224, 0.8);\n            pointer-events: none;\n            z-index: 10;\n        }\n\n        .ba-label {\n            position: absolute;\n            bottom: 12px;\n            padding: 4px 10px;\n            background: rgba(0,0,0,0.75);\n            font-family: var(--font-mono);\n            font-size: 0.72rem;\n            color: #fff;\n            border-radius: 6px;\n        }\n        .ba-label.lbl-before { right: 12px; }\n        .ba-label.lbl-after { left: 12px; color: var(--cyan-accent); }\n\n        /* RADAR INTERACTIVO DE GEOCERCAS (PILAR 4) */\n        .radar-interactive-box {\n            position: relative;\n            border-radius: 16px;\n            overflow: hidden;\n            border: 1px solid rgba(0, 163, 224, 0.3);\n        }\n\n        .radar-pin {\n            position: absolute;\n            width: 18px;\n            height: 18px;\n            background: var(--cyan-accent);\n            border-radius: 50%;\n            border: 2px solid #fff;\n            box-shadow: 0 0 12px var(--cyan-accent);\n            cursor: pointer;\n            transition: all 0.3s;\n            animation: pulsePin 2s infinite;\n        }\n\n        .radar-pin:hover {\n            transform: scale(1.3);\n            background: #fff;\n        }\n\n        @keyframes pulsePin {\n            0% { box-shadow: 0 0 0 0 rgba(0, 163, 224, 0.7); }\n            70% { box-shadow: 0 0 0 14px rgba(0, 163, 224, 0); }\n            100% { box-shadow: 0 0 0 0 rgba(0, 163, 224, 0); }\n        }\n\n        /* WHATSAPP BOT CHAT */\n        .chat-widget {\n            background: #0b141a;\n            border-radius: 16px;\n            border: 1px solid rgba(255,255,255,0.1);\n            padding: 1.25rem;\n            height: 380px;\n            display: flex;\n            flex-direction: column;\n        }\n\n        .chat-stream {\n            flex: 1;\n            overflow-y: auto;\n            display: flex;\n            flex-direction: column;\n            gap: 0.6rem;\n            padding-bottom: 0.5rem;\n        }\n\n        .c-bubble {\n            max-width: 85%;\n            padding: 8px 12px;\n            border-radius: 10px;\n            font-size: 0.8rem;\n            line-height: 1.35;\n        }\n\n        .c-bot { background: #202c33; color: #E9EDEF; align-self: flex-start; }\n        .c-user { background: #005c4b; color: #E9EDEF; align-self: flex-end; }\n\n        .chat-actions {\n            display: flex;\n            flex-wrap: wrap;\n            gap: 0.4rem;\n            padding-top: 0.6rem;\n            border-top: 1px solid rgba(255,255,255,0.08);\n        }\n\n        .c-btn {\n            background: rgba(0, 163, 224, 0.15);\n            border: 1px solid rgba(0, 163, 224, 0.3);\n            color: var(--cyan-accent);\n            font-size: 0.72rem;\n            font-weight: 600;\n            padding: 4px 10px;\n            border-radius: 16px;\n            cursor: pointer;\n            transition: all 0.2s;\n        }\n\n        .c-btn:hover { background: var(--cyan-accent); color: #000; }\n\n        /* SIMULADOR DE EMBUDO (INTERACTIVE FUNNEL) */\n        .funnel-pipeline {\n            display: grid;\n            grid-template-columns: repeat(4, 1fr);\n            gap: 1.25rem;\n            margin-top: 3rem;\n            position: relative;\n        }\n\n        .funnel-step {\n            background: var(--bg-card);\n            border: 1px solid var(--border-glass);\n            border-radius: 18px;\n            padding: 2rem 1.5rem;\n            text-align: center;\n            position: relative;\n            transition: all 0.3s ease;\n        }\n\n        .funnel-step:hover {\n            transform: translateY(-4px);\n            border-color: var(--cyan-accent);\n        }\n\n        .funnel-step::after {\n            content: '➔';\n            position: absolute;\n            right: -1rem;\n            top: 45%;\n            color: var(--cyan-accent);\n            font-size: 1.2rem;\n        }\n\n        .funnel-step:last-child::after { display: none; }\n\n        .funnel-icon {\n            width: 48px;\n            height: 48px;\n            border-radius: 50%;\n            background: rgba(0, 163, 224, 0.1);\n            color: var(--cyan-accent);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            margin: 0 auto 1.25rem auto;\n            font-size: 1.2rem;\n            border: 1px solid rgba(0, 163, 224, 0.25);\n        }\n\n        .funnel-step h5 {\n            font-family: var(--font-display);\n            font-size: 1.15rem;\n            color: #fff;\n            margin-bottom: 0.5rem;\n        }\n\n        .funnel-step p {\n            font-size: 0.82rem;\n            color: var(--text-body);\n            line-height: 1.5;\n        }\n\n        /* CONFIGURADOR MODULAR DE ALIANZA */\n        .scope-builder-box {\n            background: var(--bg-card);\n            border: 1px solid var(--border-glass);\n            border-radius: 24px;\n            padding: 3rem;\n            margin-top: 3rem;\n        }\n\n        .scope-grid {\n            display: grid;\n            grid-template-columns: repeat(2, 1fr);\n            gap: 1.5rem;\n            margin: 2rem 0;\n        }\n\n        .scope-item {\n            background: rgba(255,255,255,0.02);\n            border: 1px solid rgba(255,255,255,0.08);\n            border-radius: 16px;\n            padding: 1.5rem;\n            display: flex;\n            align-items: flex-start;\n            gap: 1rem;\n            cursor: pointer;\n            transition: all 0.25s ease;\n        }\n\n        .scope-item.selected {\n            background: rgba(0, 163, 224, 0.08);\n            border-color: var(--cyan-accent);\n            box-shadow: 0 4px 20px rgba(0, 163, 224, 0.1);\n        }\n\n        .scope-checkbox {\n            width: 22px;\n            height: 22px;\n            border-radius: 6px;\n            border: 2px solid var(--cyan-accent);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            margin-top: 2px;\n            color: #000;\n            background: transparent;\n        }\n\n        .scope-item.selected .scope-checkbox {\n            background: var(--cyan-accent);\n        }\n\n        .scope-content h5 {\n            font-family: var(--font-display);\n            font-size: 1.15rem;\n            color: #fff;\n            margin-bottom: 0.35rem;\n        }\n\n        .scope-content p {\n            font-size: 0.85rem;\n            color: var(--text-muted);\n            line-height: 1.4;\n        }\n\n        /* LIGHTBOX MODAL */\n        #lightbox-modal {\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100vw;\n            height: 100vh;\n            background: rgba(0, 0, 0, 0.92);\n            backdrop-filter: blur(15px);\n            z-index: 2000;\n            display: none;\n            align-items: center;\n            justify-content: center;\n            padding: 2rem;\n        }\n\n        #lightbox-img {\n            max-width: 90vw;\n            max-height: 85vh;\n            border-radius: 12px;\n            box-shadow: 0 0 50px rgba(0, 163, 224, 0.4);\n            border: 1px solid rgba(0, 163, 224, 0.5);\n            object-fit: contain;\n        }\n\n        #lightbox-close {\n            position: absolute;\n            top: 25px;\n            right: 35px;\n            background: transparent;\n            border: none;\n            color: #fff;\n            font-size: 2rem;\n            cursor: pointer;\n            transition: color 0.2s;\n        }\n\n        #lightbox-close:hover {\n            color: var(--cyan-accent);\n        }\n\n        /* MEETING SCHEDULER MODAL */\n        .meeting-modal-backdrop {\n            position: fixed;\n            top: 0;\n            left: 0;\n            width: 100vw;\n            height: 100vh;\n            background: rgba(2, 4, 9, 0.88);\n            backdrop-filter: blur(18px);\n            z-index: 3000;\n            display: none;\n            align-items: center;\n            justify-content: center;\n            padding: 1.5rem;\n        }\n\n        .meeting-modal-card {\n            background: linear-gradient(145deg, rgba(13, 27, 42, 0.98), rgba(7, 13, 24, 0.99));\n            border: 1px solid rgba(0, 163, 224, 0.4);\n            box-shadow: 0 25px 60px rgba(0, 0, 0, 0.8), 0 0 40px rgba(0, 163, 224, 0.15);\n            border-radius: 20px;\n            width: 100%;\n            max-width: 640px;\n            padding: 2.2rem;\n            position: relative;\n            max-height: 90vh;\n            overflow-y: auto;\n            animation: modalPopIn 0.3s ease-out;\n        }\n\n        @keyframes modalPopIn {\n            from { opacity: 0; transform: scale(0.94) translateY(15px); }\n            to { opacity: 1; transform: scale(1) translateY(0); }\n        }\n\n        .meeting-modal-close {\n            position: absolute;\n            top: 18px;\n            right: 22px;\n            background: rgba(255, 255, 255, 0.05);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n            color: #fff;\n            width: 34px;\n            height: 34px;\n            border-radius: 50%;\n            font-size: 1.3rem;\n            line-height: 1;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            cursor: pointer;\n            transition: all 0.2s;\n        }\n\n        .meeting-modal-close:hover {\n            background: rgba(239, 68, 68, 0.2);\n            border-color: #EF4444;\n            color: #EF4444;\n        }\n\n        .meeting-badge {\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            background: rgba(0, 163, 224, 0.12);\n            border: 1px solid rgba(0, 163, 224, 0.35);\n            color: var(--cyan-accent);\n            padding: 4px 10px;\n            border-radius: 20px;\n            font-family: var(--font-mono);\n            font-size: 0.68rem;\n            font-weight: 700;\n            letter-spacing: 0.8px;\n            margin-bottom: 0.6rem;\n        }\n\n        .meeting-modal-header h4 {\n            font-family: var(--font-display);\n            font-size: 1.5rem;\n            font-weight: 800;\n            color: #fff;\n            margin-bottom: 0.3rem;\n        }\n\n        .meeting-modal-header p {\n            font-size: 0.85rem;\n            color: var(--text-body);\n            line-height: 1.45;\n        }\n\n        .meeting-summary-box {\n            background: rgba(255, 255, 255, 0.025);\n            border: 1px solid rgba(255, 255, 255, 0.08);\n            border-radius: 12px;\n            padding: 0.85rem 1rem;\n            margin: 1.2rem 0;\n        }\n\n        .ms-title {\n            font-size: 0.72rem;\n            font-family: var(--font-mono);\n            color: #94A3B8;\n            text-transform: uppercase;\n            letter-spacing: 0.5px;\n            margin-bottom: 0.45rem;\n            display: flex;\n            align-items: center;\n            gap: 6px;\n        }\n\n        .ms-chips {\n            display: flex;\n            flex-wrap: wrap;\n            gap: 0.4rem;\n        }\n\n        .ms-chip {\n            font-size: 0.72rem;\n            background: rgba(0, 163, 224, 0.15);\n            border: 1px solid rgba(0, 163, 224, 0.3);\n            color: #E2E8F0;\n            padding: 3px 8px;\n            border-radius: 6px;\n            display: inline-flex;\n            align-items: center;\n            gap: 4px;\n        }\n\n        .form-grid {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 1rem;\n        }\n\n        .form-group {\n            display: flex;\n            flex-direction: column;\n            gap: 0.4rem;\n        }\n\n        .form-group label {\n            font-size: 0.76rem;\n            font-weight: 600;\n            color: #CBD5E1;\n            display: flex;\n            align-items: center;\n            gap: 6px;\n        }\n\n        .m-input {\n            background: rgba(4, 7, 17, 0.7);\n            border: 1px solid rgba(255, 255, 255, 0.15);\n            border-radius: 8px;\n            padding: 0.65rem 0.85rem;\n            color: #fff;\n            font-family: var(--font-body);\n            font-size: 0.85rem;\n            outline: none;\n            transition: all 0.2s;\n            width: 100%;\n        }\n\n        .m-input:focus {\n            border-color: var(--cyan-accent);\n            box-shadow: 0 0 10px rgba(0, 163, 224, 0.3);\n        }\n\n        .field-hint {\n            font-size: 0.68rem;\n            color: var(--text-muted);\n        }\n\n        .time-slots-grid {\n            display: grid;\n            grid-template-columns: repeat(3, 1fr);\n            gap: 0.35rem;\n        }\n\n        .time-slot-btn {\n            background: rgba(255, 255, 255, 0.04);\n            border: 1px solid rgba(255, 255, 255, 0.12);\n            border-radius: 6px;\n            color: #CBD5E1;\n            font-family: var(--font-mono);\n            font-size: 0.72rem;\n            font-weight: 600;\n            padding: 0.45rem 0.2rem;\n            cursor: pointer;\n            transition: all 0.2s;\n            text-align: center;\n        }\n\n        .time-slot-btn:hover {\n            background: rgba(0, 163, 224, 0.1);\n            border-color: var(--cyan-accent);\n            color: #fff;\n        }\n\n        .time-slot-btn.active {\n            background: var(--cyan-accent);\n            border-color: var(--cyan-accent);\n            color: #000;\n            font-weight: 700;\n            box-shadow: 0 0 12px rgba(0, 163, 224, 0.5);\n        }\n\n        .success-icon-wrapper {\n            width: 65px;\n            height: 65px;\n            border-radius: 50%;\n            background: rgba(16, 185, 129, 0.15);\n            border: 2px solid #10B981;\n            color: #10B981;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 2.2rem;\n            margin: 0 auto;\n            box-shadow: 0 0 25px rgba(16, 185, 129, 0.3);\n        }\n\n        .success-badge-confirm {\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            background: rgba(16, 185, 129, 0.1);\n            border: 1px solid rgba(16, 185, 129, 0.3);\n            color: #34D399;\n            padding: 5px 12px;\n            border-radius: 20px;\n            font-size: 0.75rem;\n            font-family: var(--font-mono);\n        }\n\n        @media (max-width: 640px) {\n            .meeting-modal-card { padding: 1.5rem 1.15rem; }\n            .form-grid { grid-template-columns: 1fr; gap: 0.8rem; }\n            .time-slots-grid { grid-template-columns: repeat(3, 1fr); }\n        }\n\n        /* FOOTER */\n        footer {\n            border-top: 1px solid var(--border-glass);\n            padding: 4rem 0 3rem 0;\n            background: #020409;\n            text-align: center;\n        }\n\n        .footer-brand {\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            gap: 2rem;\n            margin-bottom: 1.5rem;\n        }\n\n        .footer-copy {\n            font-size: 0.85rem;\n            color: var(--text-muted);\n        }\n\n        /* PRESENTATION MODE OVERLAY */\n        .pres-controls {\n            position: fixed;\n            bottom: 20px;\n            right: 20px;\n            background: rgba(11, 20, 38, 0.92);\n            backdrop-filter: blur(15px);\n            border: 1px solid var(--border-glass);\n            border-radius: 50px;\n            padding: 8px 18px;\n            display: flex;\n            align-items: center;\n            gap: 12px;\n            z-index: 1000;\n            box-shadow: 0 10px 25px rgba(0,0,0,0.6);\n        }\n\n        .pres-btn {\n            background: transparent;\n            border: none;\n            color: var(--text-title);\n            cursor: pointer;\n            font-size: 0.9rem;\n            padding: 6px 10px;\n            border-radius: 20px;\n            transition: all 0.2s;\n        }\n\n        .pres-btn:hover {\n            background: rgba(255,255,255,0.1);\n            color: var(--cyan-accent);\n        }\n\n        /* PRINT STYLES */\n        @media print {\n            body { background: #fff !important; color: #000 !important; }\n            #ambient-glow, .bg-grid, header, .pres-controls, .chat-actions, .scope-checkbox, .hero-backdrop, #lightbox-modal { display: none !important; }\n            .wrapper { max-width: 100% !important; padding: 0 !important; }\n            .hero-stats-bar, .pillar-card, .comparator-box, .scope-builder-box, .funnel-step {\n                background: #fff !important;\n                border: 1px solid #ccc !important;\n                color: #000 !important;\n                box-shadow: none !important;\n                break-inside: avoid;\n            }\n            .stat-number, .pillar-info h3, .section-title, .hero h1 {\n                color: #000 !important;\n                -webkit-text-fill-color: #000 !important;\n            }\n        }\n\n        \n        \n        .btn-text-short { display: none; }\n        .btn-text-full { display: inline; }\n        @media (max-width: 768px) {\n            .btn-text-full { display: none; }\n            .btn-text-short { display: inline; }\n            .btn-action { white-space: nowrap; }\n        }\n\n        /* RESPONSIVE & DEVICE ARCHITECTURE: MOBILE & IPAD */\n        \n        /* Tablets & iPads (768px - 1024px) */\n        @media (max-width: 1024px) {\n            .wrapper { padding: 0 2rem; }\n            .hero h1 { font-size: 2.8rem; }\n            .hero-stats-bar {\n                grid-template-columns: repeat(2, 1fr);\n                gap: 1.5rem;\n                padding: 2rem;\n            }\n            .stat-card:nth-child(2)::after { display: none; }\n            .comparator-box {\n                grid-template-columns: 1fr 1fr;\n                gap: 1.5rem;\n                padding: 2rem;\n            }\n            .pillar-card {\n                padding: 2.25rem;\n                margin-bottom: 2.5rem;\n            }\n            .pillar-grid, .pillar-grid.reverse {\n                grid-template-columns: 1.1fr 1fr;\n                gap: 2rem;\n            }\n            .pillar-info h3 { font-size: 1.7rem; }\n            .funnel-pipeline { grid-template-columns: repeat(2, 1fr); gap: 1.25rem; }\n            .funnel-step::after { display: none; }\n            .scope-grid { grid-template-columns: repeat(2, 1fr); gap: 1.25rem; }\n        }\n\n        /* Mobile Phones (<= 768px - iPhone, Android) */\n        @media (max-width: 768px) {\n            .wrapper { padding: 0 1.15rem !important; }\n            header { padding: 0.75rem 0; }\n            .nav-container {\n                display: flex;\n                justify-content: space-between;\n                align-items: center;\n                gap: 0.5rem;\n            }\n            .brand-cluster {\n                display: flex;\n                align-items: center;\n                gap: 0.5rem;\n            }\n            .brand-logo-img { height: 18px; }\n            .brand-divider { height: 14px; }\n            .brand-text { font-size: 0.85rem; }\n            .target-badge {\n                font-size: 0.62rem;\n                padding: 2px 7px;\n                display: none; /* Keep header clean on mobile */\n            }\n            .nav-actions { display: flex; gap: 0.4rem; }\n            .btn-action {\n                padding: 0.45rem 0.85rem;\n                font-size: 0.75rem;\n                border-radius: 6px;\n            }\n            .btn-action.hide-mobile { display: none !important; }\n            \n            .hero { padding: 2.5rem 0 1.5rem 0; }\n            .hero-pill {\n                font-size: 0.75rem;\n                padding: 0.35rem 1rem;\n                margin-bottom: 1.25rem;\n            }\n            .hero h1 {\n                font-size: 2.15rem;\n                line-height: 1.18;\n                margin-bottom: 1.25rem;\n            }\n            .hero-manifesto {\n                font-size: 0.98rem;\n                line-height: 1.65;\n                margin-bottom: 1.75rem;\n            }\n            \n            /* 2x2 Clean Dashboard Grid for Mobile */\n            .hero-stats-bar {\n                grid-template-columns: repeat(2, 1fr) !important;\n                gap: 1.25rem 0.75rem !important;\n                padding: 1.5rem 1rem !important;\n                border-radius: 16px;\n            }\n            .stat-card {\n                padding: 0.5rem 0.25rem;\n            }\n            .stat-card:nth-child(1)::after,\n            .stat-card:nth-child(3)::after {\n                content: \"\";\n                position: absolute;\n                right: -0.375rem;\n                top: 15%;\n                height: 70%;\n                width: 1px;\n                background: rgba(255, 255, 255, 0.08);\n            }\n            .stat-card:nth-child(2)::after,\n            .stat-card:nth-child(4)::after {\n                display: none !important;\n            }\n            .stat-number {\n                font-size: 2.2rem !important;\n                margin-bottom: 0.25rem;\n            }\n            .stat-number .unit {\n                font-size: 1.3rem !important;\n            }\n            .stat-label {\n                font-size: 0.72rem !important;\n                line-height: 1.2;\n            }\n            .stat-sub {\n                font-size: 0.65rem !important;\n            }\n            \n            .comparator-box {\n                grid-template-columns: 1fr !important;\n                padding: 1.25rem !important;\n                gap: 1.25rem !important;\n                margin-top: 1.5rem !important;\n                border-radius: 16px;\n            }\n            .comp-column {\n                padding: 1.15rem !important;\n                border-radius: 12px;\n            }\n            .comp-header {\n                gap: 0.5rem;\n                margin-bottom: 1rem;\n            }\n            .comp-header h4 { font-size: 1.1rem; }\n            .comp-list { gap: 0.85rem; }\n            .comp-list li {\n                font-size: 0.85rem;\n                gap: 0.6rem;\n                line-height: 1.45;\n            }\n            \n            .pillar-card {\n                padding: 1.25rem !important;\n                margin-bottom: 1.75rem !important;\n                border-radius: 16px;\n            }\n            .pillar-header {\n                margin-bottom: 1rem;\n                padding-bottom: 0.75rem;\n            }\n            .pillar-num {\n                font-size: 0.72rem;\n                padding: 3px 9px;\n            }\n            .pillar-grid, .pillar-grid.reverse {\n                grid-template-columns: 1fr !important;\n                gap: 1.25rem !important;\n            }\n            .pillar-info h3 {\n                font-size: 1.35rem;\n                margin-bottom: 0.65rem;\n            }\n            .pillar-info p {\n                font-size: 0.88rem;\n                line-height: 1.55;\n                margin-bottom: 1rem;\n            }\n            .deliverable-tags { gap: 0.4rem; }\n            .d-tag {\n                font-size: 0.74rem;\n                padding: 5px 9px;\n                border-radius: 6px;\n            }\n            \n            .visual-asset-frame { border-radius: 12px; }\n            .visual-badge-overlay {\n                bottom: 8px;\n                left: 8px;\n                padding: 4px 8px;\n                font-size: 0.65rem;\n            }\n            \n            .before-after-container {\n                height: 220px;\n                border-radius: 12px;\n            }\n            .chat-widget {\n                height: 380px;\n                padding: 0.9rem;\n                border-radius: 12px;\n            }\n            .c-bubble { font-size: 0.75rem; }\n            .c-btn {\n                padding: 6px 10px;\n                font-size: 0.7rem;\n            }\n            \n            .funnel-pipeline {\n                grid-template-columns: 1fr !important;\n                gap: 0.85rem !important;\n                margin-top: 1.5rem !important;\n            }\n            .funnel-step {\n                padding: 1.25rem 1rem;\n                border-radius: 12px;\n            }\n            .funnel-step::after { display: none !important; }\n            .funnel-icon {\n                width: 38px;\n                height: 38px;\n                font-size: 1rem;\n                margin-bottom: 0.75rem;\n            }\n            .funnel-step h5 { font-size: 1.05rem; }\n            .funnel-step p { font-size: 0.8rem; }\n            \n            .scope-builder-box {\n                padding: 1.25rem !important;\n                margin-top: 1.5rem !important;\n                border-radius: 16px;\n            }\n            .scope-grid {\n                grid-template-columns: 1fr !important;\n                gap: 0.85rem !important;\n                margin: 1.25rem 0 !important;\n            }\n            .scope-item {\n                padding: 1rem;\n                border-radius: 10px;\n                gap: 0.75rem;\n            }\n            .scope-content h5 { font-size: 0.98rem; }\n            .scope-content p { font-size: 0.78rem; }\n            \n            footer { padding: 2.5rem 0 2rem 0; }\n            .footer-brand {\n                flex-direction: column;\n                gap: 0.5rem;\n            }\n            .footer-brand span:nth-child(2),\n            .footer-brand span:nth-child(4) { display: none; }\n            .footer-copy { font-size: 0.75rem; }\n        }\n\n        @media (max-width: 380px) {\n            .hero h1 { font-size: 1.85rem; }\n            .hero-stats-bar {\n                grid-template-columns: 1fr !important;\n            }\n            .stat-card::after { display: none !important; }\n            .section-title { font-size: 1.5rem; }\n        }\n    " }} />
      <div dangerouslySetInnerHTML={{ __html: "\n\n    <!-- Ambient Cursor Glow -->\n    <div id=\"ambient-glow\"></div>\n    <div class=\"bg-grid\"></div>\n\n    <!-- Header Navigation -->\n    <header>\n        <div class=\"wrapper nav-container\">\n            <div class=\"brand-cluster\">\n                <!-- Apolograma -->\n                <a href=\"https://apolograma.com\" target=\"_blank\" class=\"brand-badge\" style=\"display: flex; align-items: center; text-decoration: none;\">\n                    <img src=\"/assets/apolograma-logo-v2.png\" alt=\"Apolograma Studio\" class=\"brand-logo-img\">\n                </a>\n                <div class=\"brand-divider\"></div>\n                <!-- Frontera -->\n                <div class=\"brand-badge\">\n                    <span class=\"brand-text\">FRONTERA</span>\n                </div>\n                <div class=\"brand-divider\"></div>\n                <span class=\"target-badge\"><i class=\"fa fa-hospital\"></i> Presentación: Hospital Ángeles</span>\n            </div>\n\n            <div class=\"nav-actions\">\n                <button class=\"btn-action btn-outline\" onclick=\"window.print()\">\n                    <i class=\"fa fa-print\"></i> Exportar Dossier PDF\n                </button>\n                <button class=\"btn-action btn-primary hide-mobile\" onclick=\"togglePresentationMode()\">\n                    <i class=\"fa fa-expand\"></i> Modo Presentación\n                </button>\n            </div>\n        </div>\n    </header>\n\n    <!-- HERO: CARTA DE PRESENTACIÓN & MANIFIESTO CON STAGE CINEMÁTICO -->\n    <section class=\"hero\" id=\"sec-hero\">\n        <div class=\"hero-backdrop\"></div>\n        <div class=\"wrapper hero-content\">\n            <div class=\"hero-pill\">\n                <span class=\"dot\"></span>\n                <span>Carta de Presentación Oficial & Media Kit Integral</span>\n            </div>\n\n            <h1>\n                Estrategia, Diseño, Software y el <br>\n                <span class=\"gradient-text\">Medio Digital #1 de la Frontera</span>\n            </h1>\n\n            <p class=\"hero-manifesto\">\n                No somos una agencia que sube fotos a redes sociales; somos la alianza entre <strong>Frontera</strong> (el medio digital con mayor alcance y viralidad de la región) y <strong>Apolograma Interactive Studio</strong> (estudio de estrategia, diseño editorial, compra de medios e ingeniería de software).\n                <br><br>\n                Ponemos este ecosistema completo al servicio de la <strong>Dirección General de Hospital Ángeles Ciudad Juárez</strong>.\n            </p>\n\n            <!-- DOMINANT METRICS BAR -->\n            <div class=\"hero-stats-bar\">\n                <div class=\"stat-card\">\n                    <div class=\"stat-number\">\n                        <span id=\"counter-views\">76.4</span><span class=\"unit\">M</span>\n                    </div>\n                    <div class=\"stat-label\">Visualizaciones / Mes</div>\n                    <div class=\"stat-sub\">Tráfico orgánico auditado en Facebook</div>\n                </div>\n\n                <div class=\"stat-card\">\n                    <div class=\"stat-number\">\n                        <span id=\"counter-fb\">410</span><span class=\"unit\">K</span>\n                    </div>\n                    <div class=\"stat-label\">Comunidad Directa FB</div>\n                    <div class=\"stat-sub\">70% Adultos 25-44 años (Decisores de salud)</div>\n                </div>\n\n                <div class=\"stat-card\">\n                    <div class=\"stat-number\">\n                        <span id=\"counter-ep\">32</span><span class=\"unit\">%</span>\n                    </div>\n                    <div class=\"stat-label\">Audiencia El Paso / USA</div>\n                    <div class=\"stat-sub\">Pacientes potenciales transfronterizos</div>\n                </div>\n\n                <div class=\"stat-card\">\n                    <div class=\"stat-number\">\n                        <span id=\"counter-ig\">69</span><span class=\"unit\">K</span>\n                    </div>\n                    <div class=\"stat-label\">Comunidad Instagram</div>\n                    <div class=\"stat-sub\">Alta interacción en Maternidad y Estética</div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <div class=\"wrapper\">\n\n        <!-- COMPARATOR: TRADITIONAL AGENCY VS APOLOGRAMA + FRONTERA -->\n        <section id=\"sec-comparator\" style=\"padding-top: 2rem;\">\n            <div class=\"section-tag\"><i class=\"fa fa-scale-balanced\"></i> Diagnóstico de Enfoque</div>\n            <h2 class=\"section-title\">El Cambio de Paradigma en la Comunicación Médica</h2>\n            <p class=\"section-subtitle\">\n                Por qué el modelo de agencia tradicional no genera impacto para un hospital de alta especialidad.\n            </p>\n\n            <div class=\"comparator-box\">\n                <!-- Traditional -->\n                <div class=\"comp-column comp-traditional\">\n                    <div class=\"comp-header\">\n                        <i class=\"fa fa-circle-xmark\" style=\"color: #EF4444; font-size: 1.4rem;\"></i>\n                        <h4>La Agencia Tradicional</h4>\n                    </div>\n                    <ul class=\"comp-list\">\n                        <li><i class=\"fa fa-xmark\"></i> <span>Posts genéricos con fotografías de stock y frases médicas frías.</span></li>\n                        <li><i class=\"fa fa-xmark\"></i> <span>Cero tracción orgánica (dependencia 100% de pauta descalificada).</span></li>\n                        <li><i class=\"fa fa-xmark\"></i> <span>Se envía al paciente a conmutadores saturados que nadie responde.</span></li>\n                        <li><i class=\"fa fa-xmark\"></i> <span>Improvisación semanal sin planeación editorial estructurada.</span></li>\n                    </ul>\n                </div>\n\n                <!-- Apolograma + Frontera -->\n                <div class=\"comp-column comp-future\">\n                    <div class=\"comp-header\">\n                        <i class=\"fa fa-circle-check\" style=\"color: var(--cyan-accent); font-size: 1.4rem;\"></i>\n                        <h4>Ecosistema Apolograma + Frontera</h4>\n                    </div>\n                    <ul class=\"comp-list\">\n                        <li><i class=\"fa fa-check\"></i> <span><strong>76.4M de vistas</strong> en formato micro-documental con médicos especialistas.</span></li>\n                        <li><i class=\"fa fa-check\"></i> <span><strong>Planeación estratégica</strong> con metodología de 13 puntos y entrega auditada.</span></li>\n                        <li><i class=\"fa fa-check\"></i> <span><strong>Pauta con geocercas</strong> en El Paso (Coronado, UTEP) y zonas premium de Juárez.</span></li>\n                        <li><i class=\"fa fa-check\"></i> <span><strong>Asistente de WhatsApp 24/7</strong> que pre-califica y cierra citas en 30s.</span></li>\n                    </ul>\n                </div>\n            </div>\n        </section>\n\n        <!-- THE 5 PILLARS OF AGENCY CAPABILITY -->\n        <section id=\"sec-pillars\">\n            <div class=\"section-tag\"><i class=\"fa fa-layer-group\"></i> Nuestros 5 Pilares de Servicio</div>\n            <h2 class=\"section-title\">La Infraestructura Completa de la Agencia</h2>\n            <p class=\"section-subtitle\">\n                Cinco capacidades integradas bajo una sola dirección para cubrir desde la atención masiva hasta la conversión clínica.\n            </p>\n\n            <!-- PILAR 1: FRONTERA MEDIA -->\n            <div class=\"pillar-card\" style=\"margin-top: 3rem;\">\n                <div class=\"pillar-header\">\n                    <span class=\"pillar-num\">PILAR 01</span>\n                    <span style=\"font-family: var(--font-mono); font-size: 0.85rem; color: var(--cyan-accent);\">DIFUSIÓN MASIVA REGIONAL</span>\n                </div>\n                <div class=\"pillar-grid\">\n                    <div class=\"pillar-info\">\n                        <h3>El Medio de Comunicación Digital Líder: Frontera</h3>\n                        <p>\n                            Ponemos a disposición de Hospital Ángeles la plataforma con mayor viralidad orgánica de Ciudad Juárez y El Paso. No compramos alcance inflado; contamos historias humanas con equipo cinematográfico 4K que conectan con la comunidad.\n                        </p>\n                        <div class=\"deliverable-tags\">\n                            <span class=\"d-tag\"><i class=\"fa fa-video\"></i> FN1 Hits (Videoreels 9:16)</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-newspaper\"></i> Reportajes Documentales</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-tower-broadcast\"></i> Coberturas en Vivo</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-chart-line\"></i> 76.4M Vistas Mensuales</span>\n                        </div>\n                    </div>\n                    <div class=\"visual-asset-frame\" onclick=\"openLightbox('/assets/hospital-angeles/pilar1_spotlight_doctor.jpg')\">\n                        <img src=\"/assets/hospital-angeles/pilar1_spotlight_doctor.jpg\" alt=\"Producción Cinematográfica Frontera\" class=\"visual-asset-img\" loading=\"lazy\">\n                        <div class=\"visual-badge-overlay\">\n                            <i class=\"fa fa-video\" style=\"color: var(--cyan-accent);\"></i> Formato: Ángeles Medical Spotlight (4K 9:16)\n                        </div>\n                        <div class=\"zoom-hint\"><i class=\"fa fa-magnifying-glass-plus\"></i></div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- PILAR 2: CONTENT STRATEGY & DUAL RIGOR -->\n            <div class=\"pillar-card\">\n                <div class=\"pillar-header\">\n                    <span class=\"pillar-num\">PILAR 02</span>\n                    <span style=\"font-family: var(--font-mono); font-size: 0.85rem; color: var(--cyan-accent);\">ESTRATEGIA & GOBERNANZA INSTITUCIONAL</span>\n                </div>\n                <div class=\"pillar-grid reverse\">\n                    <!-- Dual Governance Blueprint Card -->\n                    <div class=\"gov-blueprint-card\">\n                        <div class=\"gb-header\">\n                            <div class=\"gb-title\">\n                                <i class=\"fa fa-shield-halved\" style=\"color: var(--cyan-accent);\"></i>\n                                <span>SISTEMA DE GOBERNANZA // APOLOGRAMA</span>\n                            </div>\n                            <div class=\"gb-badge\">PROTOCOLO DIRECCIÓN</div>\n                        </div>\n                        \n                        <div class=\"gb-body\">\n                            <!-- Col 1: Jefatura Médica -->\n                            <div class=\"gb-track gb-track-med\">\n                                <div class=\"gb-track-title\">\n                                    <i class=\"fa fa-user-doctor\"></i> DIRECCIÓN MÉDICA\n                                </div>\n                                <ul class=\"gb-list\">\n                                    <li><i class=\"fa fa-circle-check\"></i> <span><b>Rigor Clínico:</b> Cero slogans banales o imprecisiones médicas.</span></li>\n                                    <li><i class=\"fa fa-circle-check\"></i> <span><b>Prestigio del Especialista:</b> Tratamiento digno y ético de la ciencia médica.</span></li>\n                                    <li><i class=\"fa fa-circle-check\"></i> <span><b>Validación Previa:</b> Aprobación técnica de cada concepto antes de salir.</span></li>\n                                </ul>\n                            </div>\n\n                            <!-- Col 2: Dirección Administrativa -->\n                            <div class=\"gb-track gb-track-adm\">\n                                <div class=\"gb-track-title\">\n                                    <i class=\"fa fa-briefcase\"></i> DIRECCIÓN ADMINISTRATIVA\n                                </div>\n                                <ul class=\"gb-list\">\n                                    <li><i class=\"fa fa-circle-check\"></i> <span><b>Planificación a 30 Días:</b> Visibilidad total sin improvisaciones.</span></li>\n                                    <li><i class=\"fa fa-circle-check\"></i> <span><b>Cero Carga Interna:</b> La agencia gestiona el 100% del flujo operativo.</span></li>\n                                    <li><i class=\"fa fa-circle-check\"></i> <span><b>Cumplimiento y SLA:</b> Entregas calendarizadas en tiempo y forma.</span></li>\n                                </ul>\n                            </div>\n                        </div>\n\n                        <div class=\"gb-footer\">\n                            <span class=\"gb-status\"><i class=\"fa fa-check-double\"></i> Doble Filtro de Control de Calidad Activo</span>\n                        </div>\n                    </div>\n\n                    <div class=\"pillar-info\">\n                        <h3>Dirección Estratégica y Rigor Institucional</h3>\n                        <p>\n                            La comunicación de un hospital de alta especialidad no se puede delegar a una agencia convencional. Nuestra metodología operativa responde con precisión a los dos frentes de su mesa directiva:\n                        </p>\n                        <div style=\"margin: 1.1rem 0; display: flex; flex-direction: column; gap: 0.8rem; font-size: 0.88rem; color: var(--text-secondary); line-height: 1.5;\">\n                            <div>\n                                <strong style=\"color: #fff;\"><i class=\"fa fa-stethoscope\" style=\"color: var(--cyan-accent);\"></i> Para Dirección Médica:</strong> Rigor científico y ética profesional. Traducimos la medicina de alta especialidad a formatos modernos sin trivializar la ciencia ni comprometer el prestigio de sus especialistas.\n                            </div>\n                            <div>\n                                <strong style=\"color: #fff;\"><i class=\"fa fa-chart-pie\" style=\"color: #34D399);\"></i> Para Dirección Administrativa:</strong> Previsibilidad y control de tiempos. Sistema de planificación estructurada a 30 días, gestión autónoma y cero sobrecarga operativa para el personal del hospital.\n                            </div>\n                        </div>\n                        <div class=\"deliverable-tags\">\n                            <span class=\"d-tag\"><i class=\"fa fa-stethoscope\"></i> Rigor Científico & Ética</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-shield-check\"></i> Validación Técnica Previa</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-calendar-days\"></i> Planificación a 30 Días</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-clock\"></i> Cero Desgaste Interno</span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- PILAR 3: GRAPHIC DESIGN & ART DIRECTION -->\n            <div class=\"pillar-card\">\n                <div class=\"pillar-header\">\n                    <span class=\"pillar-num\">PILAR 03</span>\n                    <span style=\"font-family: var(--font-mono); font-size: 0.85rem; color: var(--cyan-accent);\">DISEÑO GRÁFICO & BRANDING</span>\n                </div>\n                <div class=\"pillar-grid\">\n                    <div class=\"pillar-info\">\n                        <h3>Diseño Gráfico & Dirección de Arte de Alta Gama</h3>\n                        <p>\n                            Maquetamos piezas que transmiten la pulcritud, prestigio y modernidad de Hospital Ángeles: desde carruseles médicos de alta retención hasta gráficos para pantallas de circuito cerrado 16:9 y material impreso.\n                        </p>\n                        <div class=\"deliverable-tags\">\n                            <span class=\"d-tag\"><i class=\"fa fa-images\"></i> Carruseles Educativos</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-tv\"></i> Pantallas 16:9 Hospitalarias</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-id-card\"></i> Fichas de Especialistas</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-palette\"></i> Identidad Visual Limpia</span>\n                        </div>\n                    </div>\n                    <div>\n                        <!-- Before / After Interactive Slider -->\n                        <div class=\"before-after-container\" id=\"ba-slider\" onmousemove=\"moveSlider(event)\" ontouchmove=\"moveSliderTouch(event)\">\n                            <div class=\"ba-slide ba-before\"></div>\n                            <div class=\"ba-slide ba-after\" id=\"ba-top\"></div>\n                            <div class=\"ba-handle\" id=\"ba-handle\"><i class=\"fa fa-arrows-left-right\"></i></div>\n                            <span class=\"ba-label lbl-after\"><i class=\"fa fa-sparkles\"></i> Dirección Apolograma</span>\n                            <span class=\"ba-label lbl-before\">Agencia Tradicional</span>\n                        </div>\n                        <div style=\"text-align: center; margin-top: 8px; font-size: 0.75rem; color: var(--text-muted);\">\n                            <i class=\"fa fa-hand-pointer\"></i> Arrastre el cursor para comparar la calidad visual\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- PILAR 4: MEDIA BUYING & ADS -->\n            <div class=\"pillar-card\">\n                <div class=\"pillar-header\">\n                    <span class=\"pillar-num\">PILAR 04</span>\n                    <span style=\"font-family: var(--font-mono); font-size: 0.85rem; color: var(--cyan-accent);\">MEDIA BUYING & PAUTA DIGITAL</span>\n                </div>\n                <div class=\"pillar-grid reverse\">\n                    <div class=\"radar-interactive-box visual-asset-frame\" onclick=\"openLightbox('/assets/hospital-angeles/pilar4_geofence_map.jpg')\">\n                        <img src=\"/assets/hospital-angeles/pilar4_geofence_map.jpg\" alt=\"Radar de Geocercas El Paso - Ciudad Juárez\" class=\"visual-asset-img\" loading=\"lazy\">\n                        <!-- Pulsing Markers on Map -->\n                        <div class=\"radar-pin\" style=\"top: 38%; right: 42%;\" title=\"El Paso, TX (79912 Coronado / 79902 UTEP)\"></div>\n                        <div class=\"radar-pin\" style=\"bottom: 35%; left: 45%;\" title=\"Ciudad Juárez (Campos Elíseos / Senecú)\"></div>\n                        <div class=\"visual-badge-overlay\">\n                            <i class=\"fa fa-crosshairs\" style=\"color: var(--cyan-accent);\"></i> Radar de Tráfico: El Paso (32%) & Juárez (68%)\n                        </div>\n                        <div class=\"zoom-hint\"><i class=\"fa fa-magnifying-glass-plus\"></i></div>\n                    </div>\n                    <div class=\"pillar-info\">\n                        <h3>Compra de Medios & Pauta Hipersegmentada</h3>\n                        <p>\n                            Optimizamos la inversión publicitaria en Meta Ads y Google Ads mediante segmentación por síntoma, especialidad médica y geocercas quirúrgicas en códigos postales clave de <strong>El Paso, TX (79912 Coronado, 79902 UTEP)</strong> y zonas residenciales de <strong>Ciudad Juárez (Campos Elíseos, Senecú, Valle del Sol)</strong>.\n                        </p>\n                        <div class=\"deliverable-tags\">\n                            <span class=\"d-tag\"><i class=\"fa fa-bullseye\"></i> Geocercas El Paso / Juárez</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-chart-pie\"></i> Optimización de Conversión</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-calculator\"></i> Trazabilidad Técnica</span>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <!-- PILAR 5: SOFTWARE & TECH ECOSYSTEM -->\n            <div class=\"pillar-card\">\n                <div class=\"pillar-header\">\n                    <span class=\"pillar-num\">PILAR 05</span>\n                    <span style=\"font-family: var(--font-mono); font-size: 0.85rem; color: var(--cyan-accent);\">INGENIERÍA & SOFTWARE (APOLOGRAMA)</span>\n                </div>\n                <div class=\"pillar-grid\">\n                    <div class=\"pillar-info\">\n                        <h3>Desarrollo de Software & Ecosistemas Digitales</h3>\n                        <p>\n                            Apolograma Interactive Studio desarrolla herramientas tecnológicas que reducen la fricción en la atención al paciente: landing pages de carga ultrarrápida (<1s), asistentes inteligentes de WhatsApp 24/7 y recorridos virtuales 3D (Apolograma Spaces).\n                        </p>\n                        <div class=\"deliverable-tags\">\n                            <span class=\"d-tag\"><i class=\"fa fa-bolt\"></i> Landing Pages <1s</span>\n                            <span class=\"d-tag\"><i class=\"fa-brands fa-whatsapp\"></i> Chatbots de Triaje 24/7</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-vr-cardboard\"></i> Tours 3D Spaces</span>\n                            <span class=\"d-tag\"><i class=\"fa fa-code\"></i> Software a la Medida</span>\n                        </div>\n                    </div>\n                    <div class=\"showcase-subcard\">\n                        <div class=\"chat-widget\">\n                            <div style=\"display: flex; align-items: center; gap: 8px; padding-bottom: 8px; border-bottom: 1px solid rgba(255,255,255,0.08);\">\n                                <div style=\"width: 32px; height: 32px; border-radius: 50%; background: #00A3E0; color: #000; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.8rem;\">Á</div>\n                                <div>\n                                    <div style=\"font-size: 0.82rem; font-weight: 700; color: #fff;\">Asistente Ángeles 24/7</div>\n                                    <div style=\"font-size: 0.65rem; color: #10B981;\">● En línea</div>\n                                </div>\n                            </div>\n                            <div class=\"chat-stream\" id=\"pillar-chat-stream\">\n                                <div class=\"c-bubble c-bot\">👋 Bienvenido a <b>Hospital Ángeles Juárez</b>. ¿Desea consultar turismo médico para USA o agendar con especialista?</div>\n                            </div>\n                            <div class=\"chat-actions\">\n                                <button class=\"c-btn\" onclick=\"sendPillarChat('🇺🇸 Turismo Médico (El Paso)', 'usa')\">🇺🇸 Turismo USA</button>\n                                <button class=\"c-btn\" onclick=\"sendPillarChat('❤️ Cardiología / Urgencias', 'cardio')\">❤️ Cardiología</button>\n                                <button class=\"c-btn\" onclick=\"sendPillarChat('👶 Maternidad', 'mater')\">👶 Maternidad</button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- THE CLINICAL FUNNEL (HOW EVERYTHING CONNECTS FOR ANGELES) -->\n        <section id=\"sec-funnel\">\n            <div class=\"section-tag\"><i class=\"fa fa-arrows-split-up-and-left\"></i> Sincronización Operativa</div>\n            <h2 class=\"section-title\">El Embudo Clínico Integrado para Hospital Ángeles</h2>\n            <p class=\"section-subtitle\">\n                Cómo los 5 pilares de la agencia trabajan de forma sincronizada para llevar al paciente de la pantalla al consultorio.\n            </p>\n\n            <div class=\"funnel-pipeline\">\n                <div class=\"funnel-step\">\n                    <div class=\"funnel-icon\"><i class=\"fa fa-bullhorn\"></i></div>\n                    <h5>1. Difusión Masiva</h5>\n                    <p><strong>Frontera</strong> genera autoridad y conocimiento masivo con 76.4M de vistas en formato micro-documental.</p>\n                </div>\n\n                <div class=\"funnel-step\">\n                    <div class=\"funnel-icon\"><i class=\"fa fa-crosshairs\"></i></div>\n                    <h5>2. Pauta Quirúrgica</h5>\n                    <p><strong>Apolograma Pauta</strong> filtra y re-impacta a pacientes específicos en El Paso y zonas residenciales de Juárez.</p>\n                </div>\n\n                <div class=\"funnel-step\">\n                    <div class=\"funnel-icon\"><i class=\"fa-brands fa-whatsapp\"></i></div>\n                    <h5>3. Triaje Digital</h5>\n                    <p><strong>Apolograma Software</strong> pre-califica al paciente en WhatsApp y Landing Page en menos de 30 segundos.</p>\n                </div>\n\n                <div class=\"funnel-step\">\n                    <div class=\"funnel-icon\"><i class=\"fa fa-hospital-user\"></i></div>\n                    <h5>4. Cita / Admisión</h5>\n                    <p>El paciente llega directamente canalizado al consultorio del especialista sin fricción telefónica.</p>\n                </div>\n            </div>\n        </section>\n\n        <!-- MODULAR SCOPE BUILDER -->\n        <section id=\"sec-scope\">\n            <div class=\"section-tag\"><i class=\"fa fa-sliders\"></i> Alcance Modular</div>\n            <h2 class=\"section-title\">Configurador de Alianza Institucional</h2>\n            <p class=\"section-subtitle\">\n                Seleccione los módulos prioritarios para activar la colaboración estratégica con Hospital Ángeles.\n            </p>\n\n            <div class=\"scope-builder-box\">\n                <div class=\"scope-grid\">\n                    <div class=\"scope-item selected\" onclick=\"toggleScope(this)\">\n                        <div class=\"scope-checkbox\"><i class=\"fa fa-check\"></i></div>\n                        <div class=\"scope-content\">\n                            <h5>Módulo Difusión Masiva (Frontera Hits)</h5>\n                            <p>Producción de micro-documentales y videoreels cinemáticos para redes sociales de alta viralidad.</p>\n                        </div>\n                    </div>\n\n                    <div class=\"scope-item selected\" onclick=\"toggleScope(this)\">\n                        <div class=\"scope-checkbox\"><i class=\"fa fa-check\"></i></div>\n                        <div class=\"scope-content\">\n                            <h5>Módulo Captación El Paso / West Texas</h5>\n                            <p>Campañas de pauta con geocercas en códigos postales de alto valor en El Paso y Sur de Nuevo México.</p>\n                        </div>\n                    </div>\n\n                    <div class=\"scope-item selected\" onclick=\"toggleScope(this)\">\n                        <div class=\"scope-checkbox\"><i class=\"fa fa-check\"></i></div>\n                        <div class=\"scope-content\">\n                            <h5>Módulo Asistente de WhatsApp 24/7</h5>\n                            <p>Implementación de bot inteligente para triaje de consultas, citas y canalización bilingüe.</p>\n                        </div>\n                    </div>\n\n                    <div class=\"scope-item selected\" onclick=\"toggleScope(this)\">\n                        <div class=\"scope-checkbox\"><i class=\"fa fa-check\"></i></div>\n                        <div class=\"scope-content\">\n                            <h5>Módulo Diseño & Planeación Continua</h5>\n                            <p>Dirección de arte mensual, carruseles de especialidades y pantallas de circuito cerrado 16:9.</p>\n                        </div>\n                    </div>\n                </div>\n\n                <div style=\"text-align: center; margin-top: 2rem;\">\n                    <button class=\"btn-action btn-primary\" style=\"padding: 0.8rem 2rem; font-size: 1rem;\" onclick=\"openMeetingModal()\">\n                        <i class=\"fa fa-paper-plane\"></i> Confirmar Selección para la Junta\n                    </button>\n                </div>\n            </div>\n        </section>\n\n    </div>\n\n    <!-- MEETING SCHEDULER POPUP MODAL -->\n    <div id=\"meeting-modal\" class=\"meeting-modal-backdrop\" onclick=\"closeMeetingModalOnBackdrop(event)\">\n        <div class=\"meeting-modal-card\">\n            <button class=\"meeting-modal-close\" onclick=\"closeMeetingModal()\">&times;</button>\n            \n            <!-- Modal Content State -->\n            <div id=\"meeting-form-state\">\n                <div class=\"meeting-modal-header\">\n                    <div class=\"meeting-badge\">\n                        <i class=\"fa fa-calendar-check\"></i> AGENDAR JUNTA EJECUTIVA\n                    </div>\n                    <h4>Reunión de Presentación & Diagnóstico</h4>\n                    <p>Defina la fecha y horario para la sesión estratégica con la Dirección General de Hospital Ángeles.</p>\n                </div>\n\n                <div class=\"meeting-summary-box\">\n                    <div class=\"ms-title\"><i class=\"fa fa-layer-group\"></i> Alcance Seleccionado:</div>\n                    <div id=\"meeting-selected-chips\" class=\"ms-chips\">\n                        <!-- Filled dynamically -->\n                    </div>\n                </div>\n\n                <form id=\"meeting-form\" onsubmit=\"handleMeetingSubmit(event)\">\n                    <div class=\"form-grid\">\n                        <!-- Date Picker -->\n                        <div class=\"form-group\">\n                            <label><i class=\"fa fa-calendar-day\"></i> Fecha de la Reunión (Lunes a Viernes)</label>\n                            <input type=\"date\" id=\"m-date\" required onchange=\"validateMeetingDate(this)\" class=\"m-input\">\n                            <div class=\"field-hint\">* Días hábiles de 10:00 AM a 2:00 PM</div>\n                        </div>\n\n                        <!-- Time Slots (10 AM to 2 PM) -->\n                        <div class=\"form-group\">\n                            <label><i class=\"fa fa-clock\"></i> Horario de la Sesión</label>\n                            <div class=\"time-slots-grid\">\n                                <button type=\"button\" class=\"time-slot-btn active\" onclick=\"selectTimeSlot(this, '10:00 AM')\">10:00 AM</button>\n                                <button type=\"button\" class=\"time-slot-btn\" onclick=\"selectTimeSlot(this, '11:00 AM')\">11:00 AM</button>\n                                <button type=\"button\" class=\"time-slot-btn\" onclick=\"selectTimeSlot(this, '12:00 PM')\">12:00 PM</button>\n                                <button type=\"button\" class=\"time-slot-btn\" onclick=\"selectTimeSlot(this, '01:00 PM')\">01:00 PM</button>\n                                <button type=\"button\" class=\"time-slot-btn\" onclick=\"selectTimeSlot(this, '02:00 PM')\">02:00 PM</button>\n                            </div>\n                            <input type=\"hidden\" id=\"m-time\" value=\"10:00 AM\">\n                        </div>\n                    </div>\n\n                    <div class=\"form-grid\" style=\"margin-top: 1rem;\">\n                        <!-- Attendee Name -->\n                        <div class=\"form-group\">\n                            <label><i class=\"fa fa-user\"></i> Nombre / Cargo del Directivo</label>\n                            <input type=\"text\" id=\"m-name\" placeholder=\"Ej. Dr. Martínez / Dirección Médica\" required class=\"m-input\">\n                        </div>\n\n                        <!-- Phone / WhatsApp -->\n                        <div class=\"form-group\">\n                            <label><i class=\"fa fa-phone\"></i> Teléfono o WhatsApp de Contacto</label>\n                            <input type=\"tel\" id=\"m-phone\" placeholder=\"Ej. (656) 123-4567\" required class=\"m-input\">\n                        </div>\n                    </div>\n\n                    <div style=\"margin-top: 1.5rem; text-align: center;\">\n                        <button type=\"submit\" id=\"btn-submit-meeting\" class=\"btn-action btn-primary\" style=\"width: 100%; padding: 0.9rem; font-size: 1rem; justify-content: center;\">\n                            <i class=\"fa fa-paper-plane\"></i> Confirmar y Enviar Solicitud de Junta\n                        </button>\n                    </div>\n                </form>\n            </div>\n\n            <!-- Success State -->\n            <div id=\"meeting-success-state\" style=\"display: none; text-align: center; padding: 2rem 1rem;\">\n                <div class=\"success-icon-wrapper\">\n                    <i class=\"fa fa-circle-check\"></i>\n                </div>\n                <h3 style=\"font-family: var(--font-display); color: #fff; font-size: 1.8rem; margin: 1rem 0 0.5rem 0;\">¡Reunión Agendada con Éxito!</h3>\n                <p style=\"color: var(--text-secondary); max-width: 480px; margin: 0 auto 1.5rem auto; font-size: 0.95rem; line-height: 1.6;\">\n                    Hemos registrado su solicitud de junta para el <strong id=\"succ-date\" style=\"color: #fff;\"></strong> a las <strong id=\"succ-time\" style=\"color: var(--cyan-accent);\"></strong>.\n                    <br><br>\n                    Nos pondremos en contacto al <strong id=\"succ-phone\" style=\"color: #fff;\"></strong> vía WhatsApp o llamada telefónica para formalizar los accesos y confirmar la sesión.\n                </p>\n                <div class=\"success-badge-confirm\">\n                    <i class=\"fa fa-bolt\"></i> Notificación enviada al equipo directivo de Apolograma\n                </div>\n                <button type=\"button\" class=\"btn-action btn-outline\" style=\"margin-top: 1.5rem; padding: 0.6rem 2rem;\" onclick=\"closeMeetingModal()\">\n                    Cerrar\n                </button>\n            </div>\n        </div>\n    </div>\n\n    <!-- LIGHTBOX MODAL -->\n    <div id=\"lightbox-modal\" onclick=\"closeLightbox(event)\">\n        <button id=\"lightbox-close\" onclick=\"closeLightbox(event)\"><i class=\"fa fa-xmark\"></i></button>\n        <img id=\"lightbox-img\" src=\"\" alt=\"Ampliación en Alta Definición\">\n    </div>\n\n    <!-- FOOTER -->\n    <footer>\n        <div class=\"wrapper\">\n            <div class=\"footer-brand\">\n                <img src=\"/assets/apolograma-logo-v2.png\" alt=\"Apolograma\" style=\"height: 24px;\">\n                <span style=\"color: rgba(255,255,255,0.2);\">|</span>\n                <span style=\"color: #fff; font-family: var(--font-display); font-weight: 700; font-size: 1.1rem;\">FRONTERA NÚMERO UNO</span>\n                <span style=\"color: rgba(255,255,255,0.2);\">|</span>\n                <span style=\"color: var(--cyan-accent); font-family: var(--font-display); font-weight: 700; font-size: 1.1rem;\">HOSPITAL ÁNGELES</span>\n            </div>\n            <p class=\"footer-copy\">\n                Carta de Presentación & Credenciales de Agencia preparadas exclusivamente para la Dirección General de Hospital Ángeles Ciudad Juárez.\n                <br>© 2026 Apolograma Interactive Studio & Frontera. Todos los derechos reservados.\n            </p>\n        </div>\n    </footer>\n\n    <!-- PRESENTATION MODE CONTROLS -->\n    <div class=\"pres-controls\" id=\"pres-bar\" style=\"display: none;\">\n        <span style=\"font-family: var(--font-mono); font-size: 0.75rem; color: var(--cyan-accent);\"><i class=\"fa fa-tv\"></i> MODO PRESENTACIÓN</span>\n        <button class=\"pres-btn\" onclick=\"prevSlide()\"><i class=\"fa fa-chevron-left\"></i> Anterior</button>\n        <button class=\"pres-btn\" onclick=\"nextSlide()\">Siguiente <i class=\"fa fa-chevron-right\"></i></button>\n        <button class=\"pres-btn\" onclick=\"togglePresentationMode()\"><i class=\"fa fa-xmark\"></i> Salir</button>\n    </div>\n\n    <!-- JAVASCRIPT LOGIC -->\n    " }} />
    </>
  );
}
